draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw protein 
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 20, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('PRO', W/2 - 100, H/2);

  // draw carb
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillText('CARB', W/2 + 100, H/2);

  // draw timing 
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('TIME', W/2, H/2 - 150 + 50 * Math.sin(t));

  // draw stick figure
  ctx.beginPath();
  ctx.arc(W/2, H - 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 30);
  ctx.lineTo(W/2, H - 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50);
  ctx.lineTo(W/2 - 30, H - 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50);
  ctx.lineTo(W/2 + 30, H - 70);
  ctx.stroke();

  // draw arms and legs movement
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50);
  ctx.lineTo(W/2 - 30 + 10 * Math.cos(t), H - 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50);
  ctx.lineTo(W/2 + 30 + 10 * Math.cos(t), H - 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 80);
  ctx.lineTo(W/2 - 20 + 10 * Math.sin(t), H - 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 80);
  ctx.lineTo(W/2 + 20 + 10 * Math.sin(t), H - 100);
  ctx.stroke();

  ctx.restore();
}
